BG=(0.04,0.06,0.14,1); PANEL=(0.09,0.12,0.23,1); BLUE=(0.12,0.35,0.68,1); PURPLE=(0.35,0.20,0.60,1); GOLD=(1,0.80,0.30,1); WHITE=(0.95,0.97,1,1)

class YosinGameApp(App):
    def build(self):
        self.title='YOSINGAME'
        Window.clearcolor=BG
        self.score=0; self.level=0; self.reward=3; self.owned_item='Нест'
        self.save_path=os.path.join(self.user_data_dir,'yos ingame_save.json')
        self.load_save(); self.show_home()
        return self.root
    def label(self,text,size=18,color=WHITE,height=None):
        w=Label(text=str(text),font_size=dp(size),color=color,size_hint_y=None if height else 1,height=dp(height) if height else 0, halign='center',valign='middle')
        w.bind(size=lambda inst,val:setattr(inst,'text_size',(val[0]-dp(12),None)))
        return w
    def btn(self,text,callback,color=BLUE,height=52):
        b=Button(text=text,font_size=dp(16),size_hint_y=None,height=dp(height),background_normal='',background_color=color,color=WHITE)
        b.bind(on_release=lambda *_:callback())
        return b
    def shell(self):
        self.root=BoxLayout(orientation='vertical',padding=dp(14),spacing=dp(10))
        self.root.add_widget(self.label('YOSINGAME',27,GOLD,42))
        return self.root
    def scroll(self,layout):
        sv=ScrollView(do_scroll_x=False); sv.add_widget(layout); self.root.add_widget(sv)
    def popup(self,msg):
        box=BoxLayout(orientation='vertical',padding=dp(15),spacing=dp(12))
        box.add_widget(self.label(msg,17,WHITE))
        pop=Popup(title='YOSINGAME',content=box,size_hint=(.86,.38),auto_dismiss=True)
        box.add_widget(self.btn('ХУБ',pop.dismiss,PURPLE,45)); pop.open()
    def load_save(self):
        try:
            with open(self.save_path,'r',encoding='utf-8') as f: d=json.load(f)
            self.score=max(0,int(d.get('score',0))); self.level=max(0,min(len(QUESTIONS),int(d.get('level',0))))
            self.reward=int(d.get('reward',3)); self.owned_item=d.get('owned_item','Нест')
            if self.reward not in (3,5,7): self.reward=3; self.owned_item='Нест'
        except (OSError,ValueError,TypeError): pass
    def save_game(self):
        try:
            os.makedirs(os.path.dirname(self.save_path),exist_ok=True)
            with open(self.save_path,'w',encoding='utf-8') as f: json.dump({'score':self.score,'level':self.level,'reward':self.reward,'owned_item':self.owned_item},f,ensure_ascii=False)
        except OSError: self.popup('Пешрафт нигоҳ дошта нашуд.')
    def show_home(self):
        self.shell()
        self.root.add_widget(self.label('БОЗИИ ДОНИШ',20,(.65,.82,1,1),36))
        self.root.add_widget(self.label('🏆 Холҳо: %d'%self.score,19,GOLD,36))
        self.root.add_widget(self.label('Сатҳ: %d / %d'%(min(self.level+1,len(QUESTIONS)),len(QUESTIONS)),15,WHITE,30))
        self.root.add_widget(self.btn('БОЗӢ',self.start_game,BLUE,58))
        self.root.add_widget(self.btn('ДӮКОН',self.open_shop,PURPLE,58))
        self.root.add_widget(self.btn('АЗ АВВАЛ ОҒОЗ КАРДАН',self.confirm_restart,(.20,.24,.36,1),52))
        self.root.add_widget(self.label('Пешрафт ба таври худкор нигоҳ дошта мешавад.',12,(.72,.77,.88,1),36))
    def start_game(self):
        if self.level>=len(QUESTIONS): self.show_finished(); return
        self.show_question()
    def show_question(self):
        self.shell(); cat,q,answers,correct=QUESTIONS[self.level]
        row=BoxLayout(size_hint_y=None,height=dp(32)); row.add_widget(self.label('Савол %d/%d'%(self.level+1,len(QUESTIONS)),13,(.65,.82,1,1))); row.add_widget(self.label('Хол: %d'%self.score,14,GOLD)); self.root.add_widget(row)
        self.root.add_widget(self.label(cat,15,(.55,.9,.72,1),30))
        self.root.add_widget(self.label(q,19,WHITE,110))
        choices=list(enumerate(answers)); random.shuffle(choices)
        layout=GridLayout(cols=1,spacing=dp(8),size_hint_y=None); layout.bind(minimum_height=layout.setter('height'))
        for i,a in choices: layout.add_widget(self.btn(a,lambda i=i:self.answer(i),PANEL,55))
        self.scroll(layout); self.root.add_widget(self.btn('МЕНЮ',self.show_home,(.20,.24,.36,1),42))
    def answer(self,choice):
        correct=QUESTIONS[self.level][3]
        if choice==correct: self.score+=self.reward; msg='Дуруст! +%d хол'%self.reward
        else: msg='Ҷавоби нодуруст. Хол нагирифтӣ.'
        self.level+=1; self.save_game()
        if self.level>=len(QUESTIONS): self.show_finished()
        else: self.show_question()
        self.popup(msg)
    def open_shop(self):
        self.shell(); self.root.add_widget(self.label('ДӮКОН',24,GOLD,42)); self.root.add_widget(self.label('Холҳо: %d'%self.score,18,GOLD,35)); self.root.add_widget(self.label('Ашёи фаъол: %s | Мукофот: %d'%(self.owned_item,self.reward),14,WHITE,42))
        self.root.add_widget(self.btn('ОДӢ — 400 ХОЛ | ҷавоби дуруст: 5 хол',lambda:self.buy_item(400,5,'Одӣ'),BLUE,68))
        self.root.add_widget(self.btn('ҚАВӢ — 700 ХОЛ | ҷавоби дуруст: 7 хол',lambda:self.buy_item(700,7,'Қавӣ'),PURPLE,68))
        self.root.add_widget(self.btn('МЕНЮИ АСОСӢ',self.show_home,(.20,.24,.36,1),48))
    def buy_item(self,price,reward,name):
        if self.reward>=reward: self.popup('Ту аллакай ҳамин ё мукофоти беҳтар дорӣ.'); return
        if self.score<price: self.popup('Холҳо намерасанд!'); return
        self.score-=price; self.reward=reward; self.owned_item=name; self.save_game(); self.open_shop(); self.popup('Харид шуд! Акнун барои ҷавоби дуруст %d хол мегирӣ.'%reward)
    def confirm_restart(self):
        box=BoxLayout(orientation='vertical',padding=dp(12),spacing=dp(10)); box.add_widget(self.label('Сатҳ аз аввал сар шавад? Холҳо ва харид нигоҳ дошта мешаванд.',16))
        pop=Popup(title='Тасдиқ',content=box,size_hint=(.88,.38))
        row=BoxLayout(spacing=dp(8),size_hint_y=None,height=dp(48)); row.add_widget(self.btn('ҲА',lambda:(setattr(self,'level',0),self.save_game(),pop.dismiss(),self.start_game()),BLUE)); row.add_widget(self.btn('НЕ',pop.dismiss,PURPLE)); box.add_widget(row); pop.open()
    def show_finished(self):
        self.shell(); self.root.add_widget(self.label('ОФАРИН!',28,GOLD,55)); self.root.add_widget(self.label('Ту ҳамаи %d саволро гузаштӣ!'%len(QUESTIONS),18,WHITE,60)); self.root.add_widget(self.label('Холҳои ту: %d'%self.score,20,GOLD,45)); self.root.add_widget(self.btn('БОЗӢ АЗ НАВ',self.confirm_restart,BLUE)); self.root.add_widget(self.btn('МЕНЮИ АСОСӢ',self.show_home,PURPLE))

if __name__=='__main__': YosinGameApp().run()
